function flattenObject(obj) {
  var result = {};

  if (obj === null || typeof obj !== "object" || Array.isArray(obj)) {
    return result;
  }

  var frames = [{ value: obj, prefix: "", keys: [], index: 0 }];
  var key;
  var frame;
  var child;
  var path;
  var childKeys;
  var childKey;

  for (key in obj) {
    if (Object.prototype.propertyIsEnumerable.call(obj, key)) {
      frames[0].keys.push(key);
    }
  }

  while (frames.length > 0) {
    frame = frames[frames.length - 1];

    if (frame.index >= frame.keys.length) {
      frames.pop();
      continue;
    }

    key = frame.keys[frame.index++];
    child = frame.value[key];
    path = frame.prefix === "" ? key : frame.prefix + "." + key;

    if (child !== null && typeof child === "object" && !Array.isArray(child)) {
      childKeys = [];

      for (childKey in child) {
        if (Object.prototype.propertyIsEnumerable.call(child, childKey)) {
          childKeys.push(childKey);
        }
      }

      frames.push({
        value: child,
        prefix: path,
        keys: childKeys,
        index: 0
      });
    } else {
      Object.defineProperty(result, path, {
        value: child,
        enumerable: true,
        configurable: true,
        writable: true
      });
    }
  }

  return result;
}
